import unittest


class TestSortNumbers(unittest.TestCase):

    def test_basic_sorting(self):
        self.assertEqual(sort_numbers("three one five"), "one three five")

    def test_single_number(self):
        self.assertEqual(sort_numbers("seven"), "seven")

    def test_empty_string(self):
        self.assertEqual(sort_numbers(""), "")

    def test_already_sorted(self):
        self.assertEqual(sort_numbers("one two three"), "one two three")

    def test_reverse_sorted(self):
        self.assertEqual(sort_numbers("nine eight seven"), "seven eight nine")

    def test_duplicates(self):
        self.assertEqual(sort_numbers("two one two"), "one two two")

    def test_all_numbers(self):
        result = sort_numbers("nine one five three seven two eight four six zero")
        self.assertEqual(result, "zero one two three four five six seven eight nine")

    def test_extra_spaces(self):
        self.assertEqual(sort_numbers("three  one"), "one three")

    def test_all_same(self):
        self.assertEqual(sort_numbers("four four four"), "four four four")

    def test_two_numbers(self):
        self.assertEqual(sort_numbers("five two"), "two five")


if __name__ == "__main__":
    unittest.main()
